	result_ch := chan JAIDETrainingExample{cap: 2000}
	mut visited := map[string]bool{}
	mut visited_lock := sync.new_mutex()
	mut pages_processed := 0
	mut pages_lock := sync.new_mutex()
	mut writer_done := false
	mut writer_done_lock := sync.new_mutex()
	go fn [result_ch, mut writer_done, mut writer_done_lock] () {
		mut file := os.create(output_file) or { return }
		defer { file.close() }
		for {
			ex := <-result_ch or { break }
			line := json.encode(ex)
			file.writeln(line) or { continue }
		}
		writer_done_lock.@lock()
		writer_done = true
		writer_done_lock.unlock()
	}()
	for i in 0 .. global_crawl_concurrency {
		go fn [crawl_task_ch, translate_in_ch, mut visited, mut visited_lock, mut pages_processed, mut pages_lock] () {
			for {
				task := <-crawl_task_ch or { break }
				visited_lock.@lock()
				if task.url in visited {
					visited_lock.unlock()
					continue
				}
				visited[task.url] = true
				visited_lock.unlock()
				html := scrape_url(task.url) or {
					time.sleep(200 * time.millisecond)
					continue
				}
				content, subjects := extract_scientific_content(html)
				if content.len >= min_content_len {
					translate_in_ch <- ContentTask{url: task.url, content: content, html: html, subjects: subjects}
				}
				if task.depth < max_depth {
					links := extract_arxiv_links(html, base_url)
					for link in links {
						visited_lock.@lock()
						is_visited := link in visited
						visited_lock.unlock()
						if !is_visited {
							crawl_task_ch <- ScrapeTask{url: link, depth: task.depth + 1}
						}
					}
				}
				pages_lock.@lock()
				pages_processed++
				if pages_processed >= max_pages {
					pages_lock.unlock()
					continue
				}
				pages_lock.unlock()
				time.sleep(request_delay_ms * time.millisecond)
			}
		}()
	}
	for mi, model in models {
		mut limiter := rate_limiters[mi]
		worker_num := if model.workers > 0 { model.workers } else { 10 }
		for _ in 0 .. worker_num {
			go fn [translate_in_ch, result_ch, model, mut limiter] () {
				for {
					task := <-translate_in_ch or { break }
					translated, proc_time, token_count := translate_with_cerebras(task.content, model, mut limiter) or {
						time.sleep(200 * time.millisecond)
						continue
					}
					if translated.len < 50 {
						continue
					}
					quality := calculate_quality_score(task.content, translated)
					if quality < quality_threshold {
						continue
					}
					ex := make_example(task.url, task.content, translated, model.name, task.subjects, proc_time, token_count)
					result_ch <- ex
				}
			}()
		}
	}
	crawl_task_ch <- ScrapeTask{url: base_url, depth: 0}
	start_pages := [
		base_url + '/list/cs/new',
		base_url + '/list/cs/recent',
		base_url + '/list/astro-ph/new',
		base_url + '/list/cond-mat/new',
		base_url + '/list/gr-qc/new',
		base_url + '/list/hep-th/new',
		base_url + '/list/math/new',
		base_url + '/list/quant-ph/new',
		base_url + '/archive/cs',
		base_url + '/archive/math',
		base_url + '/help',
	]
	for u in start_pages {
		crawl_task_ch <- ScrapeTask{url: u, depth: 0}
	}
	mut done := false
	for !done {
		time.sleep(3 * time.second)
		pages_lock.@lock()
		count := pages_processed
		pages_lock.unlock()
		if count >= max_pages {
			done = true
		}
	}
	crawl_task_ch.close()
	time.sleep(10 * time.second)
	translate_in_ch.close()
	time.sleep(30 * time.second)
	result_ch.close()
	for {
		writer_done_lock.@lock()
		if writer_done {
			writer_done_lock.unlock()
			break
		}
		writer_done_lock.unlock()
		time.sleep(1 * time.second)
	}
}

