		}
	}
	translation_quality := if hungarian_indicators >= 6 { 1.0 } else if hungarian_indicators >= 4 { 0.9 } else if hungarian_indicators >= 2 { 0.75 } else { 0.5 }
	content_words := count_words(content)
	translated_words := count_words(translated)
	word_ratio := if content_words > 0 { f64(translated_words) / f64(content_words) } else { 0.0 }
	word_score := if word_ratio >= 0.6 && word_ratio <= 1.4 { 1.0 } else if word_ratio >= 0.4 && word_ratio <= 2.0 { 0.75 } else { 0.5 }
	final_score := (length_score * 0.2) + (science_score * 0.2) + (math_score * 0.15) + (structure_score * 0.1) + (translation_quality * 0.25) + (word_score * 0.1)
	return final_score
}

fn estimate_token_count(text string) int {
	base_estimate := text.len / 4
	word_estimate := count_words(text) * 2
	avg := int((f64(base_estimate) + f64(word_estimate)) * 0.5)
	if avg < 50 {
		return 50 + 150
	}
	return avg + 200
}

fn translate_with_cerebras(content string, model ModelConfig, mut rate_limiter RateLimiter) !(string, i64, int) {
	start_time := time.now().unix_milli()
	estimated_tokens := estimate_token_count(content) * 2
	rate_limiter.check_and_wait(estimated_tokens)!
	mut chunks := []string{}
	usable_context := if model.max_context > 1200 { model.max_context - 1200 } else { model.max_context }
	if content.len > usable_context {
		chunk_size := usable_context
		for i := 0; i < content.len; i += chunk_size {
			end := if i + chunk_size < content.len { i + chunk_size } else { content.len }
			chunks << content[i..end]
		}
	} else {
		chunks << content
	}
	mut full_translation := strings.new_builder(content.len * 2)
	for idx, chunk in chunks {
		request := CompletionRequest{
			model: model.name
			messages: [
				Message{role: 'system', content: 'Te egy világszínvonalú tudományos fordító vagy. Fordítási szabályok: 1) A tudományos terminológiát pontosan őrizd meg. 2) A matematikai jelölések és LaTeX kód maradjon változatlan. 3) A fordítás legyen természetes, de szakmailag precíz magyar nyelven. 4) Ne adj hozzá semmit és ne hagyj ki semmit. 5) Őrizd meg a bekezdések szerkezetét.'},
				Message{role: 'user', content: chunk},
			]
			stream: true
			max_completion_tokens: model.max_output
			temperature: model.temperature
			top_p: model.top_p
		}
		json_body := json.encode(request)
		mut req := http.new_request(http.Method.post, cerebras_api_url, json_body)
		req.add_header(http.CommonHeader.authorization, 'Bearer ${cerebras_api_key}')
		req.add_header(http.CommonHeader.content_type, 'application/json')
		req.add_header(http.CommonHeader.accept, 'text/event-stream')
		resp := req.do()!
		if resp.status_code == 429 {
			time.sleep(70 * time.second)
			return translate_with_cerebras(content, model, mut rate_limiter)!
		}
		if resp.status_code == 503 || resp.status_code == 502 || resp.status_code == 500 {
			time.sleep(5 * time.second)
			return translate_with_cerebras(content, model, mut rate_limiter)!
		}
		if resp.status_code != 200 {
			return error('api ' + model.name + ' ' + resp.status_code.str() + ' ' + resp.body)
		}
		lines := resp.body.split('\n')
		for line in lines {
			if line.starts_with('data: ') {
				data := line[6..].trim_space()
				if data.len == 0 {
					continue
				}
				if data.contains('[DONE]') {
					break
				}
				chunk_data := json.decode<StreamChunk>(data) or { continue }
				if chunk_data.choices.len > 0 {
					delta_content := chunk_data.choices[0].delta.content
					if delta_content.len > 0 {
						full_translation.write_string(delta_content)
					}
				}
			}
		}
		if idx < chunks.len - 1 {
			full_translation.write_string('\n\n')
		}
	}
	translated_text := full_translation.str()
	total_tokens := estimate_token_count(translated_text)
	processing_time := time.now().unix_milli() - start_time
	return translated_text, processing_time, total_tokens
}

struct ScrapeTask {
	url string
	depth int
}

struct ContentTask {
	url string
	content string
	html string
	subjects string
}

fn scrape_url(url string) !string {
	mut req := http.new_request(http.Method.get, url, '')
	req.add_header(http.CommonHeader.user_agent, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36 JAIDE-Scraper/1.0')
	req.add_header(http.CommonHeader.accept, 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8')
	req.add_header(http.CommonHeader.accept_language, 'en-US,en;q=0.9')
	req.add_header(http.CommonHeader.connection, 'keep-alive')
	resp := req.do()!
	if resp.status_code == 429 {
		time.sleep(15 * time.second)
		return scrape_url(url)!
	}
	if resp.status_code == 503 || resp.status_code == 502 {
		time.sleep(5 * time.second)
		return scrape_url(url)!
	}
	if resp.status_code != 200 {
		return error('http ' + resp.status_code.str())
	}
	return resp.body
}

fn extract_arxiv_links(html string, base_url string) []string {
	mut links := []string{}
	mut i := 0
	for i < html.len {
		href_idx := html.index_after('href="', i)
		if href_idx == -1 {
			break
		}
		start := href_idx + 6
		end_idx := html.index_after('"', start)
		if end_idx == -1 {
			break
		}
		link := html[start..end_idx]
		if link.starts_with('/abs/') || link.starts_with('/pdf/') || link.starts_with('/list/') || link.starts_with('/archive/') || link.starts_with('/search/') {
			full_url := if link.starts_with('http') { link } else { base_url + link }
			if !full_url.contains('.pdf') && !links.contains(full_url) {
				links << full_url
			}
		}
		i = end_idx + 1
	}
	return links
}

fn make_example(url string, content string, translated string, model_name string, subjects string, proc_time i64, token_count int) JAIDETrainingExample {
	arxiv_id := extract_arxiv_id(url)
	categories := extract_categories(subjects)
	has_math := content.contains('\\') || content.contains('$') || content.contains('^') || content.contains('_') || content.contains('∫') || content.contains('∑') || content.contains('∏')
	has_code := content.contains('```
	word_count := count_words(content)
	meta := JAIDEMetadata{
		source_url: url
		timestamp: time.now().unix()
		content_type: 'arxiv_scientific_paper'
		token_count: token_count
		quality_score: calculate_quality_score(content, translated)
		translation_model: model_name
		processing_time_ms: proc_time
		arxiv_id: arxiv_id
		categories: categories
		has_math: has_math
		has_code: has_code
		char_length: content.len
		word_count: word_count
	}
	return JAIDETrainingExample{
		instruction: 'Fordítsd le a következő tudományos cikk részletet magyarra. Őrizd meg a tudományos terminológiát pontosan, a matematikai jelöléseket és a LaTeX kódot változatlanul hagyd. A fordítás legyen természetes magyarul, de szakmailag helyes és precíz.'
		input: content
		output: translated
		metadata: meta
	}
}

fn main() {
	models := get_models()
	mut rate_limiters := []&RateLimiter{}
	for model in models {
		rate_limiters << new_rate_limiter(model.name, model)
	}
	crawl_task_ch := chan ScrapeTask{cap: 50000}
	translate_in_ch := chan ContentTask{cap: global_translate_queue_cap}
	result_ch := chan JAIDETrainingExample{cap: 2000}
	mut visited := map[string]bool{}
	mut visited_lock := sync.new_mutex()
	mut pages_processed := 0
	mut pages_lock := sync.new_mutex()
	mut writer_done := false
	mut writer_done_lock := sync.new_mutex()
	go fn [result_ch, mut writer_done, mut writer_done_lock] () {
		mut file := os.create(output_file) or { return }
		defer { file.close() }
		for {
			ex := <-result_ch or { break }
			line := json.encode(ex)
			file.writeln(line) or { continue }
		}
		writer_done_lock.@lock()
		writer_done = true
		writer_done_lock.unlock()
	}()
	for i in 0 .. global_crawl_concurrency {
		go fn [crawl_task_ch, translate_in_ch, mut visited, mut visited_lock, mut pages_processed, mut pages_lock] () {
			for {
				task := <-crawl_task_ch or { break }
				visited_lock.@lock()
				if task.url in visited {
					visited_lock.unlock()
					continue
				}
				visited[task.url] = true
				visited_lock.unlock()
				html := scrape_url(task.url) or {
					time.sleep(200 * time.millisecond)
					continue
				}
				content, subjects := extract_scientific_content(html)
				if content.len >= min_content_len {
					translate_in_ch <- ContentTask{url: task.url, content: content, html: html, subjects: subjects}
				}
				if task.depth < max_depth {
					links := extract_arxiv_links(html, base_url)
					for link in links {
						visited_lock.@lock()
						is_visited := link in visited
						visited_lock.unlock()
						if !is_visited {
							crawl_task_ch <- ScrapeTask{url: link, depth: task.depth + 1}
						}
					}
				}
				pages_lock.@lock()
				pages_processed++
				if pages_processed >= max_pages {
					pages_lock.unlock()
					continue
				}
				pages_lock.unlock()
				time.sleep(request_delay_ms * time.millisecond)
			}
		}()
	}
	for mi, model in models {
		mut limiter := rate_limiters[mi]
		worker_num := if model.workers > 0 { model.workers } else { 10 }
		for _ in 0 .. worker_num {
			go fn [translate_in_ch, result_ch, model, mut limiter] () {
				for {
					task := <-translate_in_ch or { break }
					translated, proc_time, token_count := translate_with_cerebras(task.content, model, mut limiter) or {
						time.sleep(200 * time.millisecond)
						continue
					}
					if translated.len < 50 {
						continue
					}
					quality := calculate_quality_score(task.content, translated)
					if quality < quality_threshold {
						continue
					}
					ex := make_example(task.url, task.content, translated, model.name, task.subjects, proc_time, token_count)
					result_ch <- ex
				}
			}()
		}
	}
	crawl_task_ch <- ScrapeTask{url: base_url, depth: 0}
	start_pages := [
		base_url + '/list/cs/new',
		base_url + '/list/cs/recent',
		base_url + '/list/astro-ph/new',
		base_url + '/list/cond-mat/new',
		base_url + '/list/gr-qc/new',
		base_url + '/list/hep-th/new',
		base_url + '/list/math/new',
		base_url + '/list/quant-ph/new',
		base_url + '/archive/cs',
		base_url + '/archive/math',
		base_url + '/help',
	]
	for u in start_pages {
		crawl_task_ch <- ScrapeTask{url: u, depth: 0}
	}
	mut done := false
	for !done {
		time.sleep(3 * time.second)
		pages_lock.@lock()
		count := pages_processed
		pages_lock.unlock()
		if count >= max_pages {
			done = true
		}
	}
	crawl_task_ch.close()
	time.sleep(10 * time.second)
	translate_in_ch.close()
	time.sleep(30 * time.second)
	result_ch.close()
	for {
		writer_done_lock.@lock()
		if writer_done {
			writer_done_lock.unlock()
			break
		}
		writer_done_lock.unlock()
		time.sleep(1 * time.second)
	}
}
